target.css:
:root {
  --night: #18243b;
  --night-deep: #10192b;
  --panel: #223252;
  --panel-soft: #2a3d62;
  --line: #3b5278;
  --text: #edf3ff;
  --muted: #aabbd7;
  --cyan: #73dcdf;
  --cyan-deep: #176a77;
  --gold: #f4c66b;
}

.observatory {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--night);
  color: var(--text);
}

.observatory-header {
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--night-deep);
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--cyan);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.4px;
}

.status {
  padding: 5px 8px;
  border: 1px solid var(--cyan-deep);
  border-radius: 999px;
  background: var(--panel);
  color: var(--cyan);
  font-size: 11px;
  font-weight: 700;
}

.queue {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 10px;
  padding: 12px 14px;
}

.target-card,
.schedule {
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--panel);
}

.target-card {
  padding: 12px;
}

.target-top {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.label {
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.9px;
}

.target-top h2 {
  margin-bottom: 3px;
  color: var(--text);
  font-size: 20px;
  line-height: 1;
}

.object-type {
  margin-bottom: 10px;
  color: var(--muted);
  font-size: 11px;
}

.priority {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  border-radius: 8px;
  background: var(--gold);
  color: var(--night-deep);
  font-size: 12px;
  font-weight: 800;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 9px;
}

.metric {
  padding: 7px 8px;
  border-right: 1px solid var(--line);
}

.metric:last-child {
  border-right: 0;
}

.metric span,
.exposure-copy span {
  display: block;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.metric strong {
  display: block;
  margin-top: 2px;
  color: var(--cyan);
  font-size: 15px;
  line-height: 1;
}

.exposure {
  margin-top: 10px;
}

.exposure-copy {
  display: flex;
  justify-content: space-between;
  margin-bottom: 5px;
}

.exposure-copy strong {
  color: var(--text);
  font-size: 10px;
}

.progress {
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--night-deep);
}

.progress-fill {
  display: block;
  width: 75%;
  height: 100%;
  border-radius: inherit;
  background: var(--cyan);
}

.schedule {
  padding: 10px;
}

.schedule h2 {
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0.3px;
}

.schedule ul {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.slot {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px;
  border-radius: 8px;
}

.slot.active {
  background: var(--panel-soft);
}

.slot time {
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
}

.slot strong,
.slot span {
  display: block;
}

.slot strong {
  font-size: 11px;
  line-height: 1.1;
}

.slot span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 9px;
}

.observatory-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  border-top: 1px solid var(--line);
  color: var(--cyan);
  font-size: 10px;
  font-weight: 700;
}

button {
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--panel-soft);
  color: var(--text);
  font-size: 10px;
  font-weight: 700;
}

